{
  "$schema": "./node_modules/@angular/cli/lib/config/schema.json",
  "version": 1,
  "projects": {
    "memberstack-starter": {
      "projectType": "application",
      "root": "",
      "sourceRoot": "src",
      "prefix": "app",
      "architect": {
        "build": {
          "builder": "@angular-devkit/build-angular:application",
          "defaultConfiguration": "production",
          "options": {
            "outputPath": "dist",
            "index": "src/index.html",
            "browser": "src/main.ts",
            "polyfills": [
              "zone.js"
            ],
            "tsConfig": "tsconfig.app.json",
            "styles": [
              "src/styles.css"
            ]
          },
          "configurations": {
            "production": {
              "outputHashing": "all",
              "budgets": [
                {
                  "type": "initial",
                  "maximumWarning": "500kB",
                  "maximumError": "1MB"
                },
                {
                  "type": "anyComponentStyle",
                  "maximumWarning": "4kB",
                  "maximumError": "8kB"
                }
              ]
            },
            "development": {
              "optimization": false,
              "extractLicenses": false,
              "sourceMap": true,
              "fileReplacements": [
                {
                  "replace": "src/environments/environment.ts",
                  "with": "src/environments/environment.development.ts"
                }
              ]
            }
          }
        },
        "serve": {
          "builder": "@angular-devkit/build-angular:dev-server",
          "defaultConfiguration": "development",
          "configurations": {
            "production": {
              "buildTarget": "memberstack-starter:build:production"
            },
            "development": {
              "buildTarget": "memberstack-starter:build:development"
            }
          }
        }
      }
    }
  }
}

#!/usr/bin/env node
/**
 * Lets a host set the Memberstack key by environment variable.
 *
 * Angular has no `.env` support: `environment.ts` is a TypeScript file that gets
 * compiled into the bundle. That is fine when you own the machine and can edit
 * the file, and it is why the other five starters read an env var while this one
 * does not.
 *
 * It stops being fine the moment someone deploys from a Git repo — Vercel,
 * Netlify, Cloud Build, anything. There is no file to edit, only environment
 * variables, and without this the deployed site ships whatever key happens to be
 * committed.
 *
 * So: if NG_APP_MEMBERSTACK_PUBLIC_KEY is set, this writes it into
 * environment.ts before the build. If it is NOT set, this does nothing at all
 * and the committed file is used exactly as before.
 *
 * That "does nothing" branch is load-bearing. It means the README's instruction
 * — put your Live key in environment.ts — stays true for everyone building
 * locally, and nobody's edit is silently overwritten by a blank variable.
 *
 * The NG_APP_ prefix follows the convention @ngx-env/builder established, so it
 * reads as an Angular browser-facing variable rather than a server secret.
 */

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

/**
 * EVERY environment file, not just environment.ts.
 *
 * Angular picks the file by build configuration: `ng build` defaults to
 * production and reads environment.ts, while `ng serve` defaults to development
 * and `fileReplacements` swaps in environment.development.ts. Writing only the
 * first meant setting the variable fixed the deployed site and left `npm run
 * dev` authenticating with the literal placeholder -- every call rejected with
 * "The provided public key is invalid", on the one path a developer uses while
 * building. Found by the browser smoke test; nothing else looks at dev.
 */
const ENV_DIR = fileURLToPath(new URL("../src/environments/", import.meta.url));
const VAR = "NG_APP_MEMBERSTACK_PUBLIC_KEY";

const key = process.env[VAR]?.trim();

if (!key) {
  console.log(`[set-env] ${VAR} not set — using environment.ts as committed.`);
  process.exit(0);
}

// A key that is not a key is worth failing on. Shipping a build whose auth
// silently rejects every call is far more expensive to debug than a failed
// build, and this is the only moment we can still tell the difference.
if (!/^pk_(sb_)?[A-Za-z0-9]+$/.test(key)) {
  console.error(
    `[set-env] ${VAR} is "${key}", which is not a Memberstack public key.\n` +
      `          Public keys start with pk_ (Live) or pk_sb_ (Test Mode).`
  );
  process.exit(1);
}

const FIELD = /memberstackPublicKey:\s*"[^"]*"/;

const files = readdirSync(ENV_DIR).filter((name) => name.endsWith(".ts"));
const written = [];

for (const name of files) {
  const path = join(ENV_DIR, name);
  const source = readFileSync(path, "utf8");

  // Test that the field EXISTS, rather than that the text changed. Those are
  // the same thing exactly once: the first build. Every rebuild after that
  // already holds the key, so a changed/unchanged comparison reports "field
  // missing" and fails a deploy that is perfectly fine — and hosts rebuild
  // constantly.
  if (!FIELD.test(source)) continue;

  writeFileSync(path, source.replace(FIELD, `memberstackPublicKey: "${key}"`));
  written.push(name);
}

// None at all means the field was renamed or the files moved. Refuse rather
// than serve an app that cannot authenticate for a reason nothing reports.
if (written.length === 0) {
  console.error(
    `[set-env] No file in ${ENV_DIR} contains memberstackPublicKey.\n` +
      `          Refusing to build rather than deploy an app that cannot authenticate.`
  );
  process.exit(1);
}

console.log(
  `[set-env] Wrote ${VAR} (${
    key.startsWith("pk_sb_") ? "Test Mode" : "Live"
  }) into: ${written.join(", ")}`
);

import { Component, inject, OnInit } from "@angular/core";
import { FormsModule } from "@angular/forms";
import { MemberService } from "./member.service";
import { memberstack } from "./memberstack";

@Component({
  selector: "app-account",
  standalone: true,
  imports: [FormsModule],
  template: `
    @if (members.error()) {
      <p class="notice">Could not reach Memberstack: {{ members.error() }}</p>
    } @else {
      @if (members.member(); as member) {
      <div class="auth">
        <span class="eyebrow">Account</span>
        <h1>Your details</h1>
        <p class="sub">
          This reads and writes the same custom fields your signup form collected.
        </p>

        <div class="card">
          @if (saveError) { <p class="err">{{ saveError }}</p> }
          @if (saved) { <p class="ok">Saved.</p> }

          <form (ngSubmit)="save()">
            <div class="row">
              <div>
                <label for="first">First name</label>
                <input id="first" name="first" [(ngModel)]="first" />
              </div>
              <div>
                <label for="last">Last name</label>
                <input id="last" name="last" [(ngModel)]="last" />
              </div>
            </div>

            <button type="submit" class="btn btn-primary" [disabled]="busy">
              {{ busy ? "Saving…" : "Save changes" }}
            </button>
          </form>
        </div>

        <div class="card" style="margin-top: 16px">
          <h2>Membership</h2>
          <dl class="dl">
            <div><dt>Email</dt><dd>{{ member.auth?.email }}</dd></div>
            <div><dt>Member ID</dt><dd>{{ member.id }}</dd></div>
            <div><dt>Plan</dt><dd>{{ planLabel() }}</dd></div>
          </dl>

          @if (!activePlans().length) {
            <p class="hint">
              No plan is needed — this site gates on being signed in. To gate on
              a plan instead, pass <code>plans</code> at signup or call
              <code>addPlan()</code>.
            </p>
          }
        </div>
      </div>
      }
    }
  `,
})
export class AccountComponent implements OnInit {
  readonly members = inject(MemberService);

  first = "";
  last = "";
  saved = false;
  saveError = "";
  busy = false;

  // Seeded once, on init. Re-seeding on every change would clobber whatever the
  // person is typing.
  ngOnInit() {
    const fields = this.members.member()?.customFields ?? {};
    this.first = fields["first-name"] ?? "";
    this.last = fields["last-name"] ?? "";
  }

  activePlans(): any[] {
    return this.members.member()?.planConnections?.filter((p: any) => p.active) ?? [];
  }

  planLabel(): string {
    const plans = this.activePlans();
    return plans.length ? plans.map((p: any) => p.planId).join(", ") : "None";
  }

  async save() {
    this.busy = true;
    this.saved = false;
    this.saveError = "";
    try {
      // updateMember takes the whole customFields object. Keys missing from
      // your dashboard are dropped silently, same as at signup.
      await memberstack.updateMember({
        customFields: { "first-name": this.first, "last-name": this.last },
      });
      await this.members.refresh();
      this.saved = true;
    } catch (err: any) {
      this.saveError = err?.message || "Could not save those changes.";
    }
    this.busy = false;
  }
}

import { Component, inject } from "@angular/core";
import { Title } from "@angular/platform-browser";
import { Router, RouterLink, RouterLinkActive, RouterOutlet } from "@angular/router";
import { site } from "../site.config";
import { MemberService } from "./member.service";

@Component({
  selector: "app-root",
  standalone: true,
  imports: [RouterOutlet, RouterLink, RouterLinkActive],
  template: `
    <header class="nav">
      <a routerLink="/" class="brand">{{ site.name }}</a>

      <nav class="nav-links">
        <!-- Rendering nothing while the session resolves keeps the nav from
             flickering "Log in" at a member who is already signed in. -->
        @if (members.status() !== "loading") {
          @if (members.member()) {
            <a routerLink="/members" routerLinkActive="active">Members</a>
            <a routerLink="/account" routerLinkActive="active">Account</a>
            <button type="button" class="btn btn-ghost" (click)="logout()">
              Log out
            </button>
          } @else {
            <a routerLink="/login">Log in</a>
            <a routerLink="/signup" class="btn btn-primary btn-sm">Sign up</a>
          }
        }
      </nav>
    </header>

    <main><router-outlet /></main>

    <footer class="foot">
      <span>
        {{ site.name }} is a Memberstack starter. Replace
        <code>site.config.ts</code> with your own and this becomes your site.
      </span>
    </footer>
  `,
})
export class AppComponent {
  readonly members = inject(MemberService);
  private readonly router = inject(Router);
  readonly site = site;

  constructor() {
    // index.html is static, so the tab title comes from site.config here
    // rather than being hardcoded in two places that can drift apart.
    inject(Title).setTitle(site.name);

    // Resolve the session once at startup. Gated routes may have resolved it
    // already via the guard; refresh() is cheap and idempotent.
    if (this.members.status() === "loading") this.members.refresh();
  }

  async logout() {
    await this.members.logout();
    this.router.navigate(["/"]);
  }
}

import type { Routes } from "@angular/router";
import { AccountComponent } from "./account.component";
import { gatedGuard } from "./gated.guard";
import { HomeComponent } from "./home.component";
import { LoginComponent } from "./login.component";
import { MembersComponent } from "./members.component";
import { SignupComponent } from "./signup.component";

export const routes: Routes = [
  { path: "", component: HomeComponent },
  { path: "signup", component: SignupComponent },
  { path: "login", component: LoginComponent },

  // canActivate runs BEFORE the component is created, so a signed-out visitor
  // never renders these at all. See gated.guard.ts.
  { path: "members", component: MembersComponent, canActivate: [gatedGuard] },
  { path: "account", component: AccountComponent, canActivate: [gatedGuard] },

  // Anything else goes home rather than showing a blank router outlet.
  { path: "**", redirectTo: "" },
];

import { inject } from "@angular/core";
import { type CanActivateFn, Router } from "@angular/router";
import { MemberService } from "./member.service";

/**
 * Route protection, in one place.
 *
 * Attach it with `canActivate: [gatedGuard]` in app.routes.ts.
 *
 * This is the nicest version of the gate in any of these starters, because
 * Angular gives it a real place to live. The guard runs BEFORE the route
 * activates, so a signed-out visitor never renders the gated component at all —
 * no "render nothing, then redirect" step, and no chance of the content
 * flashing on screen first.
 *
 * It still runs in the browser, which is the right tool for showing and hiding
 * UI. Anything that must never reach a signed-out visitor has to be checked on
 * your server too, with @memberstack/admin. A client-side check is a UX
 * affordance, not a security boundary.
 */
export const gatedGuard: CanActivateFn = async () => {
  const members = inject(MemberService);
  const router = inject(Router);

  // First navigation of the session: nobody has asked yet. Awaiting here is
  // what lets the guard decide correctly instead of guessing.
  const status =
    members.status() === "loading" ? await members.refresh() : members.status();

  // Let the route through when the SDK itself failed, so the page can show the
  // reason. Bouncing to /login would replace a real error with a login form and
  // hide the actual problem.
  if (status === "in" || members.error()) return true;

  return router.createUrlTree(["/login"]);
};

import { Component, EventEmitter, Input, Output } from "@angular/core";
import { memberstack } from "./memberstack";

/**
 * Google sign-in.
 *
 * This works the moment you run the starter — Google is enabled on every new
 * Memberstack app by default, using Memberstack's own OAuth credentials, so
 * there is no Google Cloud project to create first. Two thirds of live
 * Memberstack sites offer it, which is why it is here rather than the README.
 *
 * `allowSignup: true` means one button covers both cases: an existing member
 * signs in, a new one gets an account.
 *
 * WHY onSignedIn EXISTS. loginWithProvider opens a POPUP, it does not redirect
 * this page. The popup closes, the SDK stores the session, and the promise
 * resolves — in a document still sitting on the login form. Without this the
 * member is signed in and the screen never moves, which reads as "the button
 * did nothing" and invites a second click.
 */
@Component({
  selector: "google-button",
  standalone: true,
  template: `
    <button type="button" class="btn btn-google" (click)="go()">
      <svg viewBox="0 0 18 18" aria-hidden="true" width="18" height="18">
        <path fill="#4285F4" d="M17.64 9.2c0-.64-.06-1.25-.16-1.84H9v3.48h4.84a4.14 4.14 0 0 1-1.8 2.72v2.26h2.92c1.7-1.57 2.68-3.88 2.68-6.62z" />
        <path fill="#34A853" d="M9 18c2.43 0 4.47-.8 5.96-2.18l-2.92-2.26c-.8.54-1.84.86-3.04.86-2.34 0-4.32-1.58-5.03-3.7H.96v2.34A9 9 0 0 0 9 18z" />
        <path fill="#FBBC05" d="M3.97 10.72a5.4 5.4 0 0 1 0-3.44V4.94H.96a9 9 0 0 0 0 8.12l3.01-2.34z" />
        <path fill="#EA4335" d="M9 3.58c1.32 0 2.5.45 3.44 1.35l2.58-2.58C13.46.9 11.42 0 9 0A9 9 0 0 0 .96 4.94l3.01 2.34C4.68 5.16 6.66 3.58 9 3.58z" />
      </svg>
      {{ label }}
    </button>
  `,
})
export class GoogleButtonComponent {
  @Input({ required: true }) label!: string;
  @Output() failed = new EventEmitter<string>();
  @Output() signedIn = new EventEmitter<void>();

  async go() {
    try {
      await memberstack.loginWithProvider({ provider: "google", allowSignup: true });
      // The popup is gone and the session exists, but this page has not moved.
      this.signedIn.emit();
    } catch (err: any) {
      // A closed popup rejects here too, so this is not always worth shouting
      // about — but silence would leave the button looking broken.
      this.failed.emit(err?.message || "Google sign-in did not complete.");
    }
  }
}

import { Component } from "@angular/core";
import { RouterLink } from "@angular/router";
import { site } from "../site.config";

/**
 * The public page. No session check here on purpose — a marketing page that
 * waits on auth before it renders is a marketing page that renders slowly.
 */
@Component({
  selector: "app-home",
  standalone: true,
  imports: [RouterLink],
  template: `
    <div class="hero">
      <div class="hero-copy">
        <span class="eyebrow">{{ site.tagline }}</span>
        <h1>{{ site.hero.heading }}</h1>
        <p>{{ site.hero.body }}</p>

        <ul class="checks">
          @for (line of site.highlights; track line) {
            <li>
              <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
                <circle cx="8" cy="8" r="8" fill="#e9f2ee" />
                <path d="M4.6 8.2l2.1 2.1 4.7-4.7" fill="none" stroke="#0f5c46"
                      stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" />
              </svg>
              {{ line }}
            </li>
          }
        </ul>

        <a routerLink="/signup" class="btn btn-primary btn-lg">{{ site.hero.cta }}</a>
      </div>

      <!-- Shows what is behind the login without giving it away. -->
      <div class="preview" aria-hidden="true">
        @for (resource of site.resources.slice(0, 3); track resource.title) {
          <div class="card">
            <span class="kind">{{ resource.kind }}</span>
            <h2>{{ resource.title }}</h2>
            <p class="locked">
              <svg width="13" height="13" viewBox="0 0 16 16" aria-hidden="true">
                <path d="M5 7V5.1a3 3 0 016 0V7" fill="none" stroke="currentColor"
                      stroke-width="1.6" stroke-linecap="round" />
                <rect x="3.4" y="7" width="9.2" height="6.4" rx="1.9"
                      fill="currentColor" opacity="0.55" />
              </svg>
              Members only
            </p>
          </div>
        }
      </div>
    </div>
  `,
})
export class HomeComponent {
  readonly site = site;
}

import { Component, inject } from "@angular/core";
import { FormsModule } from "@angular/forms";
import { Router, RouterLink } from "@angular/router";
import { GoogleButtonComponent } from "./google-button.component";
import { MemberService } from "./member.service";
import { memberstack } from "./memberstack";

@Component({
  selector: "app-login",
  standalone: true,
  imports: [FormsModule, RouterLink, GoogleButtonComponent],
  template: `
    <div class="auth">
      <div class="card">
        <h1>Welcome back</h1>
        <p class="sub">Log in to reach your library.</p>

        @if (error) { <p class="err">{{ error }}</p> }

        @if (mode === "code-sent") {
          <p class="ok">We emailed a one-time code to {{ email }}.</p>
          <form (ngSubmit)="submitCode()">
            <label for="code">Your code</label>
            <input id="code" name="code" [(ngModel)]="code" inputmode="numeric" required />
            <button type="submit" class="btn btn-primary" [disabled]="busy">
              {{ busy ? "Checking…" : "Log in" }}
            </button>
          </form>
          <p class="alt">
            <button type="button" class="linkish" (click)="mode = 'password'; error = ''">
              Use a password instead
            </button>
          </p>
        } @else {
          <google-button
          label="Continue with Google"
          (failed)="error = $event"
          (signedIn)="afterGoogle()"
        />

          <div class="or">or</div>

          <form (ngSubmit)="submitPassword()">
            <label for="email">Email</label>
            <input id="email" name="email" type="email" [(ngModel)]="email"
                   autocomplete="email" required />

            <label for="password">Password</label>
            <input id="password" name="password" type="password" [(ngModel)]="password"
                   autocomplete="current-password" required />

            <button type="submit" class="btn btn-primary" [disabled]="busy">
              {{ busy ? "Logging in…" : "Log in" }}
            </button>
          </form>

          <p class="alt">
            <button type="button" class="linkish" [disabled]="busy" (click)="requestCode()">
              Email me a code instead
            </button>
          </p>
        }

        <p class="alt">New here? <a routerLink="/signup">Create an account</a></p>
      </div>
    </div>
  `,
})
export class LoginComponent {
  private readonly members = inject(MemberService);
  private readonly router = inject(Router);

  email = "";
  password = "";
  code = "";
  error = "";
  busy = false;
  mode: "password" | "code-sent" = "password";

  /**
   * Passwordless login, in two steps: Memberstack emails a one-time code, the
   * member types it back in. Adoption of this roughly triples between small
   * apps and large ones, which is why it is wired up rather than left as an
   * exercise.
   *
   * It is OFF on a new app. Turn it on in the dashboard under Authentication,
   * or the request below comes back with an error saying so.
   */
  /**
   * Google returns via a popup, so this page is still on screen when it
   * resolves. Refresh the shared session (so the nav updates) and move on.
   */
  async afterGoogle() {
    await this.members.refresh();
    this.router.navigate(["/members"]);
  }

  async requestCode() {
    this.error = "";
    if (!this.email) {
      this.error = "Enter your email first, then request a code.";
      return;
    }
    this.busy = true;
    try {
      await memberstack.sendMemberLoginPasswordlessEmail({ email: this.email });
      this.mode = "code-sent";
    } catch (err: any) {
      this.error =
        err?.message || "Could not send a code. Passwordless may be off for this app.";
    }
    this.busy = false;
  }

  async submitCode() {
    this.error = "";
    this.busy = true;
    try {
      await memberstack.loginMemberPasswordless({
        email: this.email,
        passwordlessToken: this.code,
      });
      await this.members.refresh();
      this.router.navigate(["/members"]);
    } catch (err: any) {
      this.error = err?.message || "That code did not work. Try requesting a new one.";
      this.busy = false;
    }
  }

  async submitPassword() {
    this.error = "";
    this.busy = true;
    try {
      await memberstack.loginMemberEmailPassword({
        email: this.email,
        password: this.password,
      });
      await this.members.refresh();
      this.router.navigate(["/members"]);
    } catch (err: any) {
      this.error = err?.message || "That email and password did not match.";
      this.busy = false;
    }
  }
}

import { Injectable, signal } from "@angular/core";
import { memberstack } from "./memberstack";

export type SessionStatus = "loading" | "in" | "out";

/**
 * One session for the whole app.
 *
 * A root-provided service is Angular's shared-state answer: every component
 * that injects it reads the same signals, so signing in updates the nav and the
 * page together. The React starter needs a context provider to do this; here
 * the injector does it.
 *
 * status is "loading" | "in" | "out" — three states, not two. A member object
 * alone cannot tell "signed out" apart from "we have not asked yet", and
 * conflating them is what makes a gated page flash its contents before it
 * redirects.
 */
@Injectable({ providedIn: "root" })
export class MemberService {
  readonly member = signal<any>(null);
  readonly status = signal<SessionStatus>("loading");
  readonly error = signal("");

  async refresh(): Promise<SessionStatus> {
    try {
      const { data } = await memberstack.getCurrentMember();
      this.member.set(data ?? null);
      this.status.set(data ? "in" : "out");
      this.error.set("");
    } catch (err: any) {
      // Almost always a bad public key. Without this the app renders a
      // permanently blank page with nothing on screen to explain why.
      this.member.set(null);
      this.status.set("out");
      this.error.set(err?.message || "Could not reach Memberstack.");
    }
    return this.status();
  }

  async logout() {
    await memberstack.logout();
    await this.refresh();
  }

  /** Convenience for templates: the member's first name, if it is set. */
  firstName(): string | undefined {
    return this.member()?.customFields?.["first-name"];
  }
}

import { Component, inject } from "@angular/core";
import { site } from "../site.config";
import { MemberService } from "./member.service";

@Component({
  selector: "app-members",
  standalone: true,
  template: `
    <!-- A bad public key surfaces here rather than as a blank page that never
         resolves. The guard lets this route through when the SDK failed, so the
         cause stays on screen instead of being replaced by a login form. -->
    @if (members.error()) {
      <p class="notice">
        Could not reach Memberstack: {{ members.error() }}<br />
        Check <code>memberstackPublicKey</code> in
        <code>src/environments/environment.ts</code>.
      </p>
    } @else if (members.member()) {
      <span class="eyebrow">Members</span>
      <h1>
        {{ members.firstName() ? "Welcome back, " + members.firstName() + "." : "Welcome back." }}
      </h1>
      <p class="sub">
        Everything below is behind the login. Signed out visitors get sent to
        the login page.
      </p>

      <div class="grid">
