  --muted: #5f6771;
  --line: #e7e5e0;
  --accent: #0f5c46;
  --accent-hover: #0c4a38;
  --accent-ink: #ffffff;
  --accent-soft: #e9f2ee;
  --danger: #a8321f;
  --danger-soft: #fdf0ed;
