}

body {
  margin: 0;
  min-height: 100%;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(1200px 500px at 82% -8%, #eaf3ef 0%, rgba(234, 243, 239, 0) 62%),
    var(--bg);
  color: var(--ink);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

main {
  flex: 1;
  width: 100%;
  max-width: 1060px;
  margin: 0 auto;
  padding: 40px 28px 80px;
}

/* ── nav ─────────────────────────────────────────────── */

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  max-width: 1060px;
  margin: 0 auto;
  padding: 20px 28px;
}

.brand {
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.025em;
  color: var(--ink);
  text-decoration: none;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Plain nav links. Scoped with :not(.btn) so it cannot bleed onto a link that
   is styled as a button — that collision is what made "Sign up" render dark
   green on dark green. */
.nav-links a:not(.btn) {
  padding: 7px 12px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  color: var(--muted);
  text-decoration: none;
}

.nav-links a:not(.btn):hover {
