  gap: 12px;
  grid-template-columns: 1fr 1fr;
}

/* ── buttons ─────────────────────────────────────────── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  width: 100%;
  padding: 11px 16px;
  border-radius: 10px;
  border: 1px solid transparent;
  font-size: 14px;
