  cursor: default;
}

.btn-primary,
a.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-sm {
  width: auto;
  padding: 8px 16px;
}

.btn-lg {
  width: auto;
  padding: 13px 22px;
  font-size: 15px;
}

.btn-google {
